const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-118.496, 34.008]).buffer(5000); // Santa Monica Pier, 5km buffer
  const dateStart = '2015-10-10';
  const dateEnd = '2015-10-11'; // A one-day window

  // 2. Data Acquisition & Pre-processing
  // Function to mask clouds and shadows using the QA_PIXEL band for Landsat 8 C2 L2
  function maskL8sr(image) {
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 4);
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to add NDVI and a water mask
  function addIndices(image) {
    const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
    // Water has low NIR reflectance. Masking land which has higher NIR.
    const waterMask = image.select('SR_B5').lt(0.05);
    return image.addBands(ndvi).updateMask(waterMask);
  }

  // Initial attempt with Landsat 8
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(dateStart, dateEnd);

  // Recovery: If no image, widen the date range slightly.
  if (collection.size().getInfo() === 0) {
    console.log('No L8 image on 2015-10-10. Widening search to +/- 2 days.');
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate('2015-10-08', '2015-10-13');
  }

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log('Evidence: No Landsat 8 images found within +/- 2 days of 2015-10-10.');
    console.log('C1');
    return;
  }
  console.log(`Found ${imageCount} image(s) within the date range.`);

  // Create a single cloud-free mosaic for analysis
  const image = collection.map(maskL8sr).map(addIndices).mosaic().clip(aoi);

  // 3. Analysis & Validation
  // Check for valid pixels after all masking
  const pixelCount = image.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (pixelCount === null || pixelCount === 0) {
    console.log('Evidence: Area is completely obscured by clouds or no water pixels found.');
    console.log('C2');
    return;
  }

  // Algae bloom is indicated by positive NDVI in water.
  // We'll calculate the mean NDVI and the count of pixels with NDVI > 0.
  const bloomThreshold = 0;
  const bloomPixels = image.select('NDVI').gt(bloomThreshold);
  const bloomArea = bloomPixels.multiply(ee.Image.pixelArea());

  const stats = bloomArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI');

  // getInfo() can result in null if there are no pixels.
  const bloomAreaSqM = stats ? ee.Number(stats).getInfo() : null;

  if (bloomAreaSqM === null) {
      console.log('Evidence: Calculation for bloom area failed. Potentially no valid pixels.');
      console.log('C3');
      return;
  }

  // Calculate percentage of water area with positive NDVI
  const totalWaterArea = ee.Image.pixelArea().updateMask(image.mask()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
  }).get('area').getInfo();

  const bloomPercentage = (bloomAreaSqM / totalWaterArea) * 100;

  // 4. Output Evidence and Final Answer
  console.log(`Image Date: ${ee.Image(collection.first()).date().format('YYYY-MM-dd').getInfo()}`);
  console.log(`Valid Water Pixels: ${pixelCount}`);
  console.log(`Bloom Area (NDVI > 0): ${Math.round(bloomAreaSqM / 1e6)} km^2`);
  console.log(`Bloom Percentage of Water: ${bloomPercentage.toFixed(2)}%`);

  // A significant bloom would cover more than a small fraction of the area.
  if (bloomPercentage > 1.0) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log('D');
});
